#!/usr/bin/env python3
"""Writes common-charset.txt, the characters of the common CJK font (build.py), from the full font and Unihan.

Run: python3 vendor/noto-sans-cjk/charset.py <path to Unihan.zip>

Needs only the standard library and fontTools (any version: it reads a cmap). The output is the same for the same Unihan.zip
and the same NotoSansMonoCJKsc-Regular.woff, and is checked in; build.py reads it and never needs Unihan. The set:

1. Every character the full font maps outside the Han blocks and the Hangul syllables: Latin, punctuation, fullwidth forms,
   kana, Bopomofo, Hangul jamo, Greek, Cyrillic, symbols.
2. The 2,350 Hangul syllables of KS X 1001, the Korean standard's set of syllables in everyday use (the euc-kr codec's rows
   0xB0A1 to 0xC8FE).
3. The Han characters in everyday use, from Unihan (Unicode License, https://www.unicode.org/terms_of_use.html):
   - kTGH, serial number 3500 or lower: level 1 of the Table of General Standard Chinese Characters (2013), the 3,500
     Simplified Chinese characters of everyday use;
   - kJoyoKanji: the Japanese joyo kanji;
   - kGradeLevel 1 or 2: Hong Kong's primary-school lists, the Traditional Chinese characters of everyday use.
"""

import re
import sys
import zipfile
from pathlib import Path

from fontTools.ttLib import TTFont

HERE = Path(__file__).resolve().parent
FULL = HERE / "NotoSansMonoCJKsc-Regular.woff"
OUTPUT = HERE / "common-charset.txt"

HAN_BLOCKS = ((0x2E80, 0x2FDF), (0x3400, 0x4DBF), (0x4E00, 0x9FFF), (0xF900, 0xFAFF), (0x20000, 0x3FFFF))
HANGUL_SYLLABLES = (0xAC00, 0xD7A3)
TGH_LEVEL_1 = 3500
GRADE_LEVEL_MAX = 2


def in_range(code: int, span: tuple) -> bool:
    return span[0] <= code <= span[1]


def ks_x_1001_syllables() -> set:
    found = set()
    for high in range(0xB0, 0xC9):
        for low in range(0xA1, 0xFF):
            try:
                found.add(ord(bytes([high, low]).decode("euc_kr")))
            except UnicodeDecodeError:
                pass
    return found


def unihan_fields(archive: Path) -> tuple:
    """(kTGH, kJoyoKanji, kGradeLevel) as code point to value, and the Unicode version Unihan states."""
    wanted = {"kTGH": {}, "kJoyoKanji": {}, "kGradeLevel": {}}
    version = ""
    with zipfile.ZipFile(archive) as zf:
        for name in sorted(zf.namelist()):
            for line in zf.read(name).decode("utf-8").splitlines():
                if line.startswith("# Unicode Version"):
                    version = line.split("Version", 1)[1].strip()
                elif line.startswith("U+"):
                    code, key, value = line.split("\t", 2)
                    if key in wanted:
                        wanted[key][int(code[2:], 16)] = value
    return wanted["kTGH"], wanted["kJoyoKanji"], wanted["kGradeLevel"], version


def ranges(codes: list) -> list:
    spans = []
    for code in sorted(codes):
        if spans and spans[-1][1] == code - 1:
            spans[-1][1] = code
        else:
            spans.append([code, code])
    return [f"{a:04X}" if a == b else f"{a:04X}-{b:04X}" for a, b in spans]


def parse(path: Path) -> set:
    """The code points a charset file declares."""
    found = set()
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("#") or not line.strip():
            continue
        for token in line.split():
            if not re.fullmatch(r"[0-9A-F]{4,6}(-[0-9A-F]{4,6})?", token):
                raise ValueError(f"{path.name}: {token!r} is not a code point or a range")
            low, _, high = token.partition("-")
            found.update(range(int(low, 16), int(high or low, 16) + 1))
    return found


def main() -> int:
    if len(sys.argv) != 2:
        print(__doc__.splitlines()[2].strip(), file=sys.stderr)
        return 2
    mapped = set(TTFont(FULL).getBestCmap())
    tgh, joyo, grade, version = unihan_fields(Path(sys.argv[1]))
    han = {code for code, serial in tgh.items() if int(serial.split(":")[1]) <= TGH_LEVEL_1}
    han |= set(joyo)
    han |= {code for code, level in grade.items() if int(level) <= GRADE_LEVEL_MAX}
    chosen = {
        code
        for code in mapped
        if not any(in_range(code, block) for block in HAN_BLOCKS) and not in_range(code, HANGUL_SYLLABLES)
    }
    chosen |= ks_x_1001_syllables() & mapped
    chosen |= han & mapped
    tokens = ranges(list(chosen))
    out = [
        "# The characters of NotoSansMonoCJKsc-Regular-common.woff, as hexadecimal code points and ranges.",
        f"# Generated by charset.py from the full font and Unihan (Unicode {version}); do not edit. How the set is chosen is in README.md.",
        f"# {len(chosen)} code points.",
    ]
    out += [" ".join(tokens[i : i + 10]) for i in range(0, len(tokens), 10)]
    OUTPUT.write_text("\n".join(out) + "\n", encoding="utf-8", newline="\n")
    print(f"{OUTPUT.name}: {len(chosen)} code points, {len(han & mapped)} Han (Unicode {version})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
